#include<stdio.h>
#include<unistd.h>
#include<stdlib.h>
#include<sys/wait.h>
					//请在此处添加导入相应库函数代码

int main()
{
	int p1, p2; //进程ID
  	/**********  Begin  **********/
    p1 = fork();
    if (p1 == 0) {
        execl("/bin/echo","echo","I am first process!",NULL);
        exit(0);
    }
    p2 = fork();
    if (p2 == 0) {
        execl("/bin/echo","echo","I am second process!",NULL);
        exit(0);
    }
    int s;
    waitpid(p1, &s, 0);
    waitpid(p2, &s, 0);
    execl("/bin/echo","echo","I am father process!",NULL);
	/**********  End  **********/
	return 0;
}
